ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text, ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
CREATE TYPE public.automation_status AS ENUM ('draft','active','paused');
CREATE TYPE public.trigger_type AS ENUM ('cron','new_email','new_event','new_task');
CREATE TYPE public.execution_status AS ENUM ('pending','running','success','error');
CREATE TABLE public.google_connections (user_id uuid PRIMARY KEY, access_token text NOT NULL, refresh_token text NOT NULL, expires_at timestamptz NOT NULL, scope text NOT NULL, google_email text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.google_connections TO authenticated; GRANT ALL ON public.google_connections TO service_role;
ALTER TABLE public.google_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY gc_self_read ON public.google_connections FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY gc_self_delete ON public.google_connections FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.automations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, description text, prompt text, status public.automation_status NOT NULL DEFAULT 'draft', state jsonb NOT NULL DEFAULT '{}'::jsonb, timezone text NOT NULL DEFAULT 'Indian/Reunion', model text NOT NULL DEFAULT 'google/gemini-2.5-flash-lite', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.automations TO authenticated; GRANT ALL ON public.automations TO service_role;
ALTER TABLE public.automations ENABLE ROW LEVEL SECURITY;
CREATE POLICY automations_self_all ON public.automations FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE INDEX idx_automations_user ON public.automations(user_id);
CREATE TABLE public.agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), automation_id uuid NOT NULL REFERENCES public.automations(id) ON DELETE CASCADE, name text NOT NULL, role text, instructions text NOT NULL, model text NOT NULL DEFAULT 'google/gemini-3-flash-preview', services text[] NOT NULL DEFAULT '{}', tools jsonb NOT NULL DEFAULT '[]'::jsonb, "order" integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.agents TO authenticated; GRANT ALL ON public.agents TO service_role;
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY agents_via_automation ON public.agents FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid()));
CREATE INDEX idx_agents_automation ON public.agents(automation_id);
CREATE TABLE public.triggers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), automation_id uuid NOT NULL REFERENCES public.automations(id) ON DELETE CASCADE, type public.trigger_type NOT NULL, config jsonb NOT NULL DEFAULT '{}'::jsonb, cron_expr text, enabled boolean NOT NULL DEFAULT true, last_run_at timestamptz, next_run_at timestamptz, last_error text, consecutive_failures integer DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.triggers TO authenticated; GRANT ALL ON public.triggers TO service_role;
ALTER TABLE public.triggers ENABLE ROW LEVEL SECURITY;
CREATE POLICY triggers_via_automation ON public.triggers FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid()));
CREATE INDEX idx_triggers_next_run ON public.triggers(next_run_at) WHERE enabled=true;
CREATE TABLE public.executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), automation_id uuid NOT NULL REFERENCES public.automations(id) ON DELETE CASCADE, trigger_id uuid REFERENCES public.triggers(id) ON DELETE SET NULL, status public.execution_status NOT NULL DEFAULT 'pending', input jsonb NOT NULL DEFAULT '{}'::jsonb, output jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.executions TO authenticated; GRANT ALL ON public.executions TO service_role;
ALTER TABLE public.executions ENABLE ROW LEVEL SECURITY;
CREATE POLICY executions_via_automation ON public.executions FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid()));
CREATE INDEX idx_executions_automation ON public.executions(automation_id,started_at DESC);
CREATE TABLE public.execution_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL REFERENCES public.executions(id) ON DELETE CASCADE, agent_id uuid REFERENCES public.agents(id) ON DELETE SET NULL, step integer NOT NULL DEFAULT 0, level text NOT NULL DEFAULT 'info', message text NOT NULL, payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.execution_logs TO authenticated; GRANT ALL ON public.execution_logs TO service_role;
ALTER TABLE public.execution_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY logs_via_execution ON public.execution_logs FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.executions e JOIN public.automations a ON a.id=e.automation_id WHERE e.id=execution_id AND a.user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.executions e JOIN public.automations a ON a.id=e.automation_id WHERE e.id=execution_id AND a.user_id=auth.uid()));
CREATE TABLE public.execution_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL REFERENCES public.executions(id) ON DELETE CASCADE, agent_name text, tool text, label text NOT NULL, status text NOT NULL DEFAULT 'running', input jsonb, output jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, attempts integer DEFAULT 1, duration_ms integer, error text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.execution_actions TO authenticated; GRANT ALL ON public.execution_actions TO service_role;
ALTER TABLE public.execution_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY owners_read_execution_actions ON public.execution_actions FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.executions e JOIN public.automations a ON a.id=e.automation_id WHERE e.id=execution_id AND a.user_id=auth.uid()));
CREATE TABLE public.debug_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, automation_id uuid NOT NULL REFERENCES public.automations(id) ON DELETE CASCADE, issue text NOT NULL, status text NOT NULL DEFAULT 'open', summary text, plan jsonb, attempts jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.debug_sessions TO authenticated; GRANT ALL ON public.debug_sessions TO service_role;
ALTER TABLE public.debug_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY owners_manage_debug_sessions ON public.debug_sessions FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.automations a WHERE a.id=automation_id AND a.user_id=auth.uid()));
CREATE TABLE public.debug_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.debug_sessions(id) ON DELETE CASCADE, role text NOT NULL, content text NOT NULL, payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.debug_messages TO authenticated; GRANT ALL ON public.debug_messages TO service_role;
ALTER TABLE public.debug_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY owners_manage_debug_messages ON public.debug_messages FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.debug_sessions s WHERE s.id=session_id AND s.user_id=auth.uid())) WITH CHECK (EXISTS(SELECT 1 FROM public.debug_sessions s WHERE s.id=session_id AND s.user_id=auth.uid()));
CREATE TABLE public.ui_preferences (user_id uuid PRIMARY KEY, timezone text NOT NULL DEFAULT 'Indian/Reunion', background_url text, background_opacity numeric NOT NULL DEFAULT 0.35, sidebar_collapsed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ui_preferences TO authenticated; GRANT ALL ON public.ui_preferences TO service_role;
ALTER TABLE public.ui_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY owners_manage_ui_prefs ON public.ui_preferences FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.user_ai_keys (user_id uuid PRIMARY KEY, openai_key text, gemini_key text, preferred_provider text DEFAULT 'lovable' CHECK(preferred_provider IN ('lovable','openai','gemini')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_ai_keys TO authenticated; GRANT ALL ON public.user_ai_keys TO service_role;
ALTER TABLE public.user_ai_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_ai_keys ON public.user_ai_keys FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.execution_costs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL REFERENCES public.executions(id) ON DELETE CASCADE, automation_id uuid NOT NULL REFERENCES public.automations(id) ON DELETE CASCADE, user_id uuid NOT NULL, model text, input_tokens integer DEFAULT 0, output_tokens integer DEFAULT 0, cost_usd numeric(10,6) DEFAULT 0, provider text DEFAULT 'lovable', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.execution_costs TO authenticated; GRANT ALL ON public.execution_costs TO service_role;
ALTER TABLE public.execution_costs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_costs_read ON public.execution_costs FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE INDEX execution_costs_user_idx ON public.execution_costs(user_id,created_at DESC);
CREATE TABLE public.agent_tools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, description text NOT NULL, http_method text NOT NULL DEFAULT 'GET', url text NOT NULL, headers jsonb NOT NULL DEFAULT '{}'::jsonb, body_template text, input_schema jsonb NOT NULL DEFAULT '{}'::jsonb, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.agent_tools TO authenticated; GRANT ALL ON public.agent_tools TO service_role;
ALTER TABLE public.agent_tools ENABLE ROW LEVEL SECURITY;
CREATE POLICY agent_tools_owner ON public.agent_tools FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.tick_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), duration_ms integer NOT NULL DEFAULT 0, launched_count integer NOT NULL DEFAULT 0, results jsonb NOT NULL DEFAULT '[]'::jsonb, error text);
GRANT SELECT ON public.tick_logs TO authenticated; GRANT ALL ON public.tick_logs TO service_role;
ALTER TABLE public.tick_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tick_logs_owner ON public.tick_logs FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM jsonb_array_elements(results) r JOIN public.automations a ON a.id::text=r->>'automation_id' WHERE a.user_id=auth.uid()));
CREATE INDEX tick_logs_ran_at_idx ON public.tick_logs(ran_at DESC);
CREATE OR REPLACE FUNCTION public.nexus_set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER nexus_automations_updated BEFORE UPDATE ON public.automations FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
CREATE TRIGGER nexus_google_updated BEFORE UPDATE ON public.google_connections FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
CREATE TRIGGER nexus_debug_updated BEFORE UPDATE ON public.debug_sessions FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
CREATE TRIGGER nexus_prefs_updated BEFORE UPDATE ON public.ui_preferences FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
CREATE TRIGGER nexus_keys_updated BEFORE UPDATE ON public.user_ai_keys FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
CREATE TRIGGER nexus_tools_updated BEFORE UPDATE ON public.agent_tools FOR EACH ROW EXECUTE FUNCTION public.nexus_set_updated_at();
ALTER TABLE public.executions REPLICA IDENTITY FULL;
ALTER TABLE public.execution_logs REPLICA IDENTITY FULL;
ALTER TABLE public.triggers REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.executions,public.execution_logs,public.triggers,public.execution_actions,public.debug_messages,public.execution_costs;
CREATE POLICY nexus_backgrounds_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='backgrounds' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY nexus_backgrounds_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='backgrounds' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY nexus_backgrounds_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='backgrounds' AND auth.uid()::text=(storage.foldername(name))[1]) WITH CHECK(bucket_id='backgrounds' AND auth.uid()::text=(storage.foldername(name))[1]);
CREATE POLICY nexus_backgrounds_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='backgrounds' AND auth.uid()::text=(storage.foldername(name))[1]);